(7519967, 1201173, 28742, '<td valign="top">I''m AMAZED at this. I am excited to hear a description of what/how/where. Solid 10.</td>', 'I''m AMAZED at this. I am excited to hear a description of what/how/where. Solid 10.', '2017-06-23 04:14:22.000000', NULL, 1),
(7519968, 1201609, 28742, '<td valign="top">Ah, a bartender''s view of Albert Einstein sitting at the bar in front of the blinds, lifting his glass to drink a toast to the photographer. :)</td>', 'Ah, a bartender''s view of Albert Einstein sitting at the bar in front of the blinds, lifting his glass to drink a toast to the photographer. :)', '2017-06-23 04:16:01.000000', NULL, 1),
(7519969, 1201145, 28742, '<td valign="top">lotsa lotsa. texture, muted colors, light, shadows, interesting shapes. Well done! I''ll be looking at this again, but for now, a 9.</td>', 'lotsa lotsa. texture, muted colors, light, shadows, interesting shapes. Well done! I''ll be looking at this again, but for now, a 9.', '2017-06-23 04:17:56.000000', NULL, 1),
